from typing import List

def get_solution():
    # start
    def mean_absolute_deviation(numbers: List[float]) -> float:
        if not numbers:
            return 0.0
        mean = sum(numbers) / len(numbers)
        total_diff = 0.0
        for num in numbers:
            total_diff += abs(num - mean)
        return total_diff / len(numbers)
    # end
    return mean_absolute_deviation
